// EDI 850 (X12 004010) - canonical PO object in, { fileName, edi } out.

// Trading-partner config (set once):
const SENDER_ID = 'EASYBITS', RECEIVER_ID = 'PARTNER';
const SENDER_QUAL = 'ZZ', RECEIVER_QUAL = 'ZZ';
const USAGE = 'T';            // 'T' test, 'P' production

// Map free-text units to X12 355 codes; anything unknown falls back to EA.
const UOM_MAP = {
  piece: 'EA', pieces: 'EA', pc: 'EA', pcs: 'EA', each: 'EA', ea: 'EA', unit: 'EA', units: 'EA', no: 'EA', nos: 'EA',
  box: 'BX', bx: 'BX',
  roll: 'RL', rl: 'RL',
  packet: 'PK', pkt: 'PK', pack: 'PK', pk: 'PK',
  carton: 'CT', ctn: 'CT',
  can: 'CN', tin: 'CN',
  bottle: 'BO', btl: 'BO',
  bag: 'BG', pair: 'PR', set: 'ST', dozen: 'DZ', dz: 'DZ',
  pallet: 'PL', kg: 'KG', gram: 'GR', meter: 'MR', metre: 'MR', litre: 'LT', liter: 'LT',
};
const toUom = (u) => UOM_MAP[String(u || '').trim().toLowerCase()] || 'EA';

const E = '*', S = '~', U = '>';
const po = $input.first().json;
const lines = Array.isArray(po.lines) ? po.lines : [];

const pad = (v, n) => String(v).padEnd(n).slice(0, n);
const dig = (v) => String(v).replace(/[^0-9]/g, '');
const toEdiDate = (v) => {
  const s = String(v || '').trim(); let m;
  if ((m = s.match(/^(\d{4})-(\d{2})-(\d{2})/)))            return m[1] + m[2] + m[3];
  if ((m = s.match(/^(\d{2})[.\/-](\d{2})[.\/-](\d{4})$/))) return m[3] + m[2] + m[1];
  const d = dig(s);
  return d.length === 8 ? d : dig(new Date().toISOString().slice(0, 10));
};

const now = new Date();
const y6 = dig(now.toISOString().slice(2, 10));
const y8 = dig(now.toISOString().slice(0, 10));
const time = String(now.getHours()).padStart(2, '0') + String(now.getMinutes()).padStart(2, '0');
const ctrl = dig(String(Date.now())).slice(-9).padStart(9, '0');
const ctrlN = String(Number(ctrl));
const currency = po.currency || 'AED';

const out = [];
out.push(['ISA','00',pad('',10),'00',pad('',10),SENDER_QUAL,pad(SENDER_ID,15),
  RECEIVER_QUAL,pad(RECEIVER_ID,15),y6,time,'U','00401',ctrl,'0',USAGE,U].join(E));
out.push(['GS','PO',SENDER_ID,RECEIVER_ID,y8,time,ctrlN,'X','004010'].join(E));

const tx = [];
tx.push(['ST','850','0001'].join(E));
tx.push(['BEG','00','SA',po.po_number || '','',toEdiDate(po.po_date)].join(E));
tx.push(['CUR','BY',currency].join(E));
if (po.customer) tx.push(['N1','BY', po.customer].join(E));
if (po.supplier) tx.push(['N1','VN', po.supplier].join(E));
if (po.delivery_date) tx.push(['DTM','002', toEdiDate(po.delivery_date)].join(E));

let hashQty = 0, grand = 0;
lines.forEach((ln, i) => {
  const qty = Number(ln.quantity) || 0, price = Number(ln.unit_price) || 0;
  hashQty += qty; grand += (Number(ln.line_total) || qty * price);
  const po1 = ['PO1', ln.line_number || (i + 1), qty, toUom(ln.uom), price, 'PE'];
  if (ln.item_code) po1.push('VP', ln.item_code);
  tx.push(po1.join(E));
  if (ln.description) tx.push(['PID','F','','','', String(ln.description)].join(E));
});

tx.push(['CTT', lines.length, hashQty].join(E));
tx.push(['AMT','TT', grand.toFixed(2)].join(E));
tx.push(['SE', tx.length + 1, '0001'].join(E));

const all = [...out, ...tx, ['GE','1',ctrlN].join(E), ['IEA','1',ctrl].join(E)];
const fileName = `PO_${String(po.po_number || 'unknown').replace(/[^A-Za-z0-9_-]/g, '_')}_850.edi`;

return [{ json: { fileName, edi: all.join(S) + S } }];
